css:
/*タイトル非表示*/
.title {
    display: none;
}

/*ヘッダー編集*/

 #header-link-1,  #header-link-2, #header-link-6, #header-link-8,  #header-link-9 { /*ヘッダーLINEボタン非表示*/
    display: none;
}
 #header-menu-link-1, #header-menu-link-2, #header-menu-link-6,  #header-menu-link-8, #header-menu-link-9 { /*mobileヘッダーLINEボタン非表示*/
    display: none;
}
#header-link-7 {
    background: #0092e5;
    border-radius: 50px;
    position: relative;
    display: flex;
    justify-content: space-around;
    align-items: center;
    margin: 0 auto;
    max-width: 260px;
    padding: 5px 15px;
    color: #fff;
    transition: 0.3s ease-in-out;
    border: 2px solid #0092e5;
    margin: 0 0 0 15px;
}

#header-link-7:hover {
    background:  #fff;
    color:  #0092e5;
} 


/*ヘッダー編集終わり*/
/*サイトの幅1024pxテスト*/
.titleSection__contentsWrapper, .separatedSection__contentsWrapper, .contentsFooterSection__contentsWrapper {
    max-width: 1024px !important;
    padding:0px !important;
}

/*各セクションの感覚調整*/
.contents.no-icon {
    padding-top: 0px;
}

.separatedSection {
    padding: 5rem 1rem;
}

#section-first{
    padding: 5rem 1rem 1rem;
}


/*背景色*/
.page {
  background-color: #F6F7F6;
}

.separatedSection:nth-child(even),
.contentsFooterSection {
    background-color: #fff;
}

.container {
  max-width: 100%;
  padding: 0;
}

/*各セクション幅*/
.titleSection__contentsWrapper,
.separatedSection__contentsWrapper,
.contentsFooterSection__contentsWrapper  {
  max-width: 800px;
  margin: 0 auto;
  padding: 1rem;
}



/* テキスト周り */
.notion-text{
  padding: 1rem 0.1rem;
}

.notion-h2{
    font-size: 2.5rem;
    padding: 0rem 0.1rem 1.5rem 0.1rem;
    line-height:4rem;
    text-align: center;
    margin: 0;
}
@media (max-width: 767px){
.notion-h2 {
    font-size: 1.75rem;
    padding: 0rem 0.1rem 1.5rem 0.1rem;
    line-height: 3rem;
}}

.notion-h3 {
    padding: 1rem 2px;
    font-size: 1.2rem;
}

/* =========================
   Hero (メインビジュアル)
   ※ 背景は既存指定を使用（オーバーレイ無し）
========================= */

#block-3dd6077e488780378d09e1e3d67b3e7f {
    display: none;
}
.page_id-f1187f2bd96a41ab98945550f0191729 #section-first {
    background: url(__PROTOOUT_BASE__assets/5995819df38b712c4460.webp);
    color: #fff;
    background-size: cover;
    background-position: center;
    display: flex;
    align-items: center;
}

@media (max-width: 767px) {
.page_id-f1187f2bd96a41ab98945550f0191729 #section-first {
        background-image: url(__PROTOOUT_BASE__assets/5995819df38b712c4460.webp);
    }
}

.page_id-f1187f2bd96a41ab98945550f0191729 #section-first {
  position: relative;
  display: flex;               /* 既存で align-items:center 指定済み */
  justify-content: center;
  padding: 72px 24px;
  color: #fff;
}

/* テキストブロック */
.page_id-f1187f2bd96a41ab98945550f0191729 #section-first .hero {
  position: relative;
  z-index: 1;
  max-width: 1100px;
  width: 100%;
  margin: 0 auto;
  color: inherit;
}

/* ① 一番強調：H1 */
.page_id-f1187f2bd96a41ab98945550f0191729 #section-first .text_h1 {
  font-size: 2.875rem;       /* 最重要：どーんと大きく */
  line-height: 1.18;
  letter-spacing: .01em;
  font-weight: 800;
  margin: 0 0 12px;
  text-wrap: balance;
  text-shadow: 0 2px 18px rgba(0,0,0,.28);
}

/* ② そこそこ強調：サブコピー */
.page_id-f1187f2bd96a41ab98945550f0191729 #section-first .hero__subtitle {
  font-size: 1.75rem;        /* 目立つがH1より一段弱く */
  line-height: 1.5;
  margin: 0 0 12px;
  opacity: .96;
  text-shadow: 0 1px 12px rgba(0,0,0,.22);
}

/* ③ 控えめ：説明文 */
.page_id-f1187f2bd96a41ab98945550f0191729 #section-first .subtext {
  font-size: 1.0625rem;      /* 読みやすい小さめ */
  line-height: 1.9;
  margin: 40px 0 0;
  opacity: .92;
  text-shadow: 0 1px 10px rgba(0,0,0,.2);
}

/* 「プロトアウトスタジオ」を改行・単独表示＆軽く強調 */
.page_id-f1187f2bd96a41ab98945550f0191729 #section-first .subtext .brand,
.page_id-f1187f2bd96a41ab98945550f0191729 #section-first .hero__brandline .brand {
  display: block;             /* 単独行へ */
  font-size: 1.5rem;
  font-weight: 800;
  text-decoration: underline;
  text-decoration-color: rgba(255,255,255,.55);
  text-underline-offset: .18em;
}

/* スマホのみ改行したい <br class="u-br--sp"> を有効化 */
.u-br--sp { display: none; }
@media (max-width: 767px) {
  .u-br--sp { display: inline; }
}

/* ====== レスポンシブ微調整 ====== */
@media (max-width: 1024px) {
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first {
    padding: 56px 20px;
  }
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .subtext { max-width: 60ch; }
}

@media (max-width: 767px) {
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first {
    min-height: 62vh;
    padding: 40px 18px;
    justify-content: flex-end; /* 下寄せでヒーロー感 */
  }
  /* 階層の差は維持しつつ少しだけ縮小 */
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .text_h1 {
    font-size: 2.25rem;
    line-height: 1.22;
    text-shadow: 0 2px 12px rgba(0,0,0,.26);
  }
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .hero__subtitle {
    font-size: 1.25rem;
    line-height: 1.5;
  }
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .subtext {
    font-size: 1rem;
    max-width: 100%;
  }
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .subtext .brand { font-size: 1.25rem; }
}

/* ====== フェードイン演出（任意） ====== */
@media (prefers-reduced-motion: no-preference) {
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .hero > * {
    opacity: 0;
    transform: translateY(8px);
    animation: hero-fade .6s ease-out forwards;
  }
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .text_h1        { animation-delay: .05s; }
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .hero__subtitle { animation-delay: .15s; }
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .subtext        { animation-delay: .25s; }
  @keyframes hero-fade { to { opacity: 1; transform: none; } }
}

/* スマホ（～767px） */
@media (max-width: 767px) {
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .text_h1 {
    font-size: 1.75rem;   /* ≈36px */
    line-height: 1.22;
  }
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .hero__subtitle {
    font-size: 1.25rem;   /* ≈20px */
    line-height: 1.5;
  }
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .subtext {
    font-size: 1rem;      /* 16px */
    line-height: 1.9;
  }
  .page_id-f1187f2bd96a41ab98945550f0191729 #section-first .subtext .brand {
    font-size: 1.25rem;   /* ≈20px：単独表示の強調を少しだけ維持 */
  }
}

/* スマホサイズでのフォントサイズ */
@media (max-width: 767px) {
    .separatedSection {
        padding: 5rem 1rem;
    }

    .titleSection__contentsWrapper,
    .separatedSection__contentsWrapper,
    .contentsFooterSection__contentsWrapper {
        margin: 0;
        width: 100%;
    }

    .responsive-text {
        font-size: 1.4rem; /* スマホサイズでフォントを小さくする */
    }
}

/* ==== 全体レイアウト（横並び） ==== */
.features-section {
  margin-top: 24px;           /* セクション自体はブロックのまま */
}

/* ← ここをフレックス化する（重要） */
.features-section .features {
  display: flex;
  align-items: stretch;       /* カード高さを揃える */
  gap: 50px;
  flex-wrap: nowrap;          /* 2枚を横並び固定。狭い余白なら wrap に変更可 */
}

/* 各カード（幅300pxのカードを2枚） */
.feature-card {
  flex: 0 0 300px; 
  display: flex;
  flex-direction: column;
  background-color: rgba(255, 255, 255, 0.7);
  border-radius: 8px;
  padding: 24px;
  text-align: center;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

/* タイトル（未使用なら削除OK） */
.feature-title { font-size: 1.5rem; margin-bottom: 16px; }

/* 説明文 */
.feature-desc {
  font-size: 0.9rem;
  color: #555;
  line-height: 1.6;
  margin-bottom: 20px;
}

/* ボタン共通 */
.feature-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: 4px;
  font-weight: bold;
  text-decoration: none;
  margin-top: auto;          /* ボタンを下に押し出す */
  font-size: 16px;
}

/* ボタン色 */
.feature-btn-primary   { background-color: #0092e5; color: #fff; }
.feature-btn-primary:hover { background-color: #5CACAC; }
.feature-btn-secondary { background-color: #297D98; color: #fff; }
.feature-btn-secondary:hover { background-color:#3A9BC1; }

/* 矢印 */
.arrow { margin-left: 6px; font-size: 1.2em; }

/* ==== スマホは縦並び ==== */
@media (max-width: 767px) {
  .features-section .features {
    flex-direction: column;
    gap: 24px;
    padding: 0 16px;         /* 端の余白が欲しい場合 */
  }
  .feature-card {
    flex: none;
    width: 100%;
    box-sizing: border-box;
  }
}


/*ファーストビューボタン*/

.btn_top {
        width: 250px;
        height: auto;
        position: relative;
        margin-top: 50px;
}
.btn_dw {
        width: 210px;
        height: 30px;
        padding-left: 0.1em;
        border-radius: 20px;
        border: solid 2px #0092e5;
        background-color: #fff;
        font-size: 1rem;
        font-weight: 700;
        line-height: 1;
        text-align: center;
        display: flex;
        justify-content: center;
        align-items: center;
        position: absolute;
        bottom: 35px;
        left: 50%;
        transform: translate(-50%, 0%);
        pointer-events: none;
        transition: 0.2s;
        color: #297D98;
        z-index: 2;
}
.btn_dw::before, .btn_dw::after {
        content: "";
        width: 0;
        height: 0;
        border-style: solid;
        position: absolute;
        left: 50%;
        transform: translate(-50%, 100%);
}
.btn_dw::before {
        bottom: 1px;
        border-width: 8px 5px 0 5px;
        border-color: #fff transparent transparent transparent;
        z-index: 2;
}
.btn_dw::after {
        bottom: 0;
        border-width: 11px 8px 0 8px;
        border-color:#0092e5 transparent transparent transparent;
        z-index: 1;
}
.btn_download {
        width: 100%;
        padding: 15px 30px;
        border-radius: 8px;
        font-size: 1rem;
        font-weight: 500;
        line-height: 1;
        text-align: center;
        text-decoration: none;
        display: flex;
        justify-content: center;
        align-items: center;
        box-sizing: border-box;
        background: #0092e5;
        -webkit-box-shadow: 0 5px 0 #0084cf;
        box-shadow: 0 5px 0 #0084cf;
        color: #fff;
        transition: 0.2s;
}
.btn_download:after {
  content: "";
  position: absolute;
  top: 50%;
  bottom: 0;
  right: 2rem;
  font-size: 90%;
  display: flex;
  justify-content: center;
  align-items: center;
  transition: right 0.3s;
  width: 6px;
  height: 6px;
  border-top: solid 2px currentColor;
  border-right: solid 2px currentColor;
  transform: translateY(-50%) rotate(45deg);
}
.btn_download:hover {
  background: #6bc594;
  color: #FFF;
  -webkit-box-shadow: 0 2px 0 #2c9d60;
  box-shadow: 0 2px 0 #2c9d60;
  transform: translateY(3px);
}
