/*-----こんなお悩み-----*/
ul.cp_list {
  padding: 0;
  position: relative;
}
.cp_list li {
  margin-bottom: 10px; /* ここでリストアイテムの間の隙間を指定します */
}
ul.cp_list li {
  background: #fff;
  line-height: 1.5;
  padding: 15px 50px 15px calc(50px + 2em);
  list-style-type: none!important;
  font-weight: bold; /*好みで太字に*/
  font-size: 20px;
}

@media (max-width: 767px){
    ul.cp_list li{
    padding: 15px 50px 15px calc(0px + 2em);    
    }}

ul.cp_list li:before {
    position: relative;
    content: "";
    display: inline-block;
    width: 22px;
    height: 22px;
    margin-right: 6px;
    top: 6px;
