/* トークン（お好みで調整可） */
#block-2676077e48878057ab3ae6ca022a5ab8,
#block-2676077e488780f5adbefa9796155175 {
  --logo-gap: 16px;
  --logo-box-h-pc: 200px;   /* PC時のロゴ枠 高さ */
  --logo-box-h-sp: 150px;   /* SP時のロゴ枠 高さ */
  --logo-pad: 8px;         /* ロゴ周囲の余白 */
  --logo-radius: 8px;      /* 角丸 */
  --logo-bg: #fff;
}

/* 行を4カラムのグリッドに（等間隔） */
#block-2676077e48878057ab3ae6ca022a5ab8,
#block-2676077e488780f5adbefa9796155175 {
  display: grid !important;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: var(--logo-gap);
  align-items: center;
}

/* Notionのスペーサーを無効化 */
#block-2676077e48878057ab3ae6ca022a5ab8 .notion-spacer,
#block-2676077e488780f5adbefa9796155175 .notion-spacer {
  display: none !important;
}

/* カラムの固定幅指定を打ち消し（グリッドに従わせる） */
#block-2676077e48878057ab3ae6ca022a5ab8 .notion-column,
#block-2676077e488780f5adbefa9796155175 .notion-column {
  width: auto !important;
}

