/* =========================
   CTA セクション（コンパクト版・共通）
   2ボタン横並び（スマホは縦）＋資料DL
========================= */
.cta-section {
  /* フラット色（枠線や白ボタン用） */
  --biz: #0066CC;     /* 法人 */
  --school: #FF6B35;  /* 個人 */

  /* グラデーション色 */
  --biz-grad-from:    #235c9f;
  --biz-grad-to:      #033979;
  --school-grad-from: #cb5701;
  --school-grad-to:   #ad330b;

  /* 調整ノブ */
  --btn-w: 260px;     /* 1ボタンの目安幅（PC） */
  --btn-h: 44px;      /* ボタン高さ（PC） */
  --btn-h-sp: 25px;   /* ボタン高さ（SP） */
  --btn-fs: 0.95rem;  /* フォントサイズ */
  --gap: 12px;        /* ボタン間の余白 */
  --radius: 8px;
  --shadow: 0 3px 10px rgba(0,0,0,.08);

  max-width: 840px;
  margin: 20px auto 0;
  padding: 0 12px;    /* 画面端の余白ケア */
}

/* CTAボタンをピル型に（角丸MAX） */
.cta-section { --radius: 9999px; }

/* 行レイアウト */
.cta-row {
  display: flex;
  gap: var(--gap);
  align-items: stretch;
  justify-content: center;  /* 既定は中央寄せ（後で左寄せ上書き可） */
  flex-wrap: wrap;          /* 狭い幅で折り返し */
}
.cta-row + .cta-row { margin-top: var(--gap); }

/* ボタン共通（コンパクト設計） */
.cta-btn {
  flex: 0 1 var(--btn-w);   /* 横幅コントロール */
  min-width: 220px;         /* 極端に小さくならないように */
  max-width: 320px;
  min-height: var(--btn-h);
  padding: 10px 16px;
  font-size: var(--btn-fs);
  border-radius: var(--radius);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-weight: 700;
  text-decoration: none;
  line-height: 1;
  box-shadow: var(--shadow);
  transition: transform .06s ease, box-shadow .2s ease, opacity .2s ease, filter .2s ease, background .2s ease;
  will-change: transform, filter;
  border: 0;
  color: #fff;
}

/* ===== ご指定の“他社風”グラデーション適用 ===== */
.cta-biz {
  background: linear-gradient(90deg, var(--biz-grad-from), var(--biz-grad-to));
  line-height: 1.3;
  padding: 10px 16px; /* 元指定(17px 26px 13px)はコンパクト版に合わせて控えめ */
}
.cta-school {
  background: linear-gradient(90deg, var(--school-grad-from), var(--school-grad-to));
  line-height: 1.3333333333;
  padding: 10px 16px; /* 元指定(13px 26px)は控えめに */
}

/* ホバー（少しだけ深く） */
.cta-biz:hover {
  background: linear-gradient(90deg, #1e4f8c, #023165);
}
.cta-school:hover {
  background: linear-gradient(90deg, #b84e01, #922c09);
}

/* アクティブ・フォーカス */
.cta-btn:active { transform: translateY(0); box-shadow: var(--shadow); filter: saturate(1.05); }
.cta-btn:focus-visible { outline: 3px solid rgba(0, 102, 204, .35); outline-offset: 2px; }

/* 資料DLは中立（アウトライン） */
.cta-outline {
  background: #fff;
  color: #222;
  border: 1px solid #ddd;
  flex: 0 1 var(--btn-w);
  min-height: var(--btn-h);
  padding: 10px 16px;
}

/* ダウンロード段は中央寄せ（必要に応じて左寄せに上書き可） */
.cta-row-download { justify-content: center; }

/* 矢印 */
.cta-btn .arrow { font-size: 1.05em; margin-left: 2px; }

/* スマホ：縦積み・さらに小さめに */
@media (max-width: 767px) {
  /* 角丸と高さの“ノブ”をスマホだけ控えめに */
  .cta-section {
    --radius: 18px;   /* ← 9999px だと“まん丸感”が強いので、スマホはほどよく */
    --btn-h-sp: 36px; /* ← 既定40pxから低めに（さらに下げたいなら 34px など） */
  }
}

/* =========================
   separatedSection__contentsWrapper 配下だけ左寄せ
========================= */
.separatedSection__contentsWrapper .cta-section .cta-row,
.separatedSection__contentsWrapper .cta-section .cta-row-download {
  justify-content: flex-start !important;  /* 既存の center を上書き */
}
.separatedSection__contentsWrapper .cta-section .cta-outline { margin-left: 0; }

/* スマホ時も左から並ぶ意図を明確化（任意） */
@media (max-width: 767px) {
  .separatedSection__contentsWrapper .cta-section .cta-row { align-items: stretch; }
}

